import{_ as t,o as a,c as r,ak as n}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy visual design pack","description":"Eight visual concepts created for the Gameplay First GDD edition, October 22, 2026.","frontmatter":{"title":"Chainy visual design pack","description":"Eight visual concepts created for the Gameplay First GDD edition, October 22, 2026.","source":"docs/media/gdd/gameplay-first/README.md","category":"Other documents","sourceUpdated":"2026-10-22T22:46:54+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/media/gdd/gameplay-first/readme.md","filePath":"content/docs/media/gdd/gameplay-first/readme.md"}'),i={name:"content/docs/media/gdd/gameplay-first/readme.md"};function s(d,e,o,c,l,p){return a(),r("div",null,[...e[0]||(e[0]=[n('<div><h1 id="chainy-visual-design-pack">Chainy visual design pack<a class="header-anchor" href="#chainy-visual-design-pack" aria-label="Link to this section">​</a></h1><p>Eight visual concepts created for the Gameplay First GDD edition, October 22, 2026.</p><table><thead><tr><th>File</th><th>Use</th></tr></thead><tbody><tr><td>web3-world.png</td><td>Compact harbor, merchant and workshop restoration route</td></tr><tr><td>web3-purchase.png</td><td>Review, pending and confirmed purchase states</td></tr><tr><td>blockchain-world.png</td><td>Local beacon repair and verification stations</td></tr><tr><td>blockchain-repair.png</td><td>Reference ordering, altered data and stale-copy distinction</td></tr><tr><td>ai-world.png</td><td>Separate teaching, testing and human-approval stations</td></tr><tr><td>ai-training.png</td><td>Selected training examples, new test and evidence checking</td></tr><tr><td>navigation-journal.png</td><td>World selection, chronological quest log and encyclopedia stages</td></tr><tr><td>characters.png</td><td>Explorer and proposed Sean, Matthew and Lee robot variants</td></tr></tbody></table><p>All eight are 1672 × 941 PNGs. They were generated by three visual-design subagents with the built-in image-generation tool and reviewed by the main agent. Prompts, revisions and detailed caveats are retained in <code>notes/</code>.</p><p>These are concept illustrations, not screenshots of the current Android build, licensed third-party game assets, Unity scenes, rigged models or interactive UI. Rebuild interfaces as editable Unity components with real text and tested input states. Create modular meshes and materials; do not treat a flattened PNG as a production level.</p><p>Use the GDD&#39;s rules when a simplified picture differs: the repair picture has two slots while the proposed exercise has three subsequent blocks; the purchase and training sheets compare sequential screens, not simultaneous mobile panels. AI training labels are already selected in the picture; the actual activity needs both options before selection. The AI secret-phrase request uses a neutral request icon; the behavior, not the sender&#39;s appearance, is the concern.</p><p>Production still needs consistent Explorer/robot proportions, back/cancel controls, safe-area and accessibility checks, selected/error/loading states, and measured phone performance. The illustration detail is not a mobile performance budget. Matthew&#39;s badge needs explicit links when rebuilt as an icon. Guide accent colors and badges are proposals rather than frozen character designs.</p><p>The approved direction is fixed isometric, restrained faceted low-poly, blue-haired yellow-clad Explorer, white screen-faced robots and readable navy/cyan interface panels. Do not copy another game&#39;s maps, characters or HUD. Luis owns production art, Miguel UI, Christian implementation/integration, Sherwin design decisions and Sean authored project documentation.</p></div>',1)])])}const g=t(i,[["render",s]]);export{u as __pageData,g as default};
